517	// --- Ordered physical coverage --------------------------------------------------------
518	//
519	// ONE defect, one correction, and it is NOT a bank. The frontier rule credited a
520	// frame only when the body's whole projection fell under `previousUnits +
521	// displacement`, so an ordinary rounded corner — walk through the vertex,
522	// overshoot it, turn onto the next leg already a little way along — left a
523	// residual that no later frame could ever clear, because from then on both the
524	// projection and the ceiling advanced at exactly the same rate. Measured live
525	// (`producer-common-entry-crossing-review.json`, call 298 of
526	// `verifier/captures/common-entry-crossing/run1`): credit exactly 6 at vertex
527	// (-44, 51.05, 16), foot 0.2742 past it, projection 6.2944830004 against a
528	// ceiling of 6.1635971455, frozen from there on.
529	//
530	// The correction is to measure what the body PHYSICALLY COVERED, in order, from
531	// its real previous foot to its real current foot, rather than to hand it an
532	// allowance it may spend anywhere:
533	//
534	//   * A vertex is REACHED only by an actual motion that crosses its incoming
535	//     plane — previous foot strictly short of it, current foot at or past it —
536	//     AND that passes within the unchanged 0.35 vertex reach of the vertex
537	//     itself. Both facts come from the two real feet. Standing on the far side
538	//     proves nothing; being the nearest vertex proves nothing.
539	//   * Vertices are reached STRICTLY IN ORDER, one route index at a time. A body
540	//     that cut a corner has not reached it, so nothing beyond it can be covered
541	//     however far or long it walks afterwards, and the z 15.82 refusal and its
542	//     walk-back-and-re-traverse repair are exactly preserved.
543	//   * Within the leg it has actually reached, credit is the body's own position
544	//     on that leg, clamped to the leg and to the corridor, and monotone. It is
545	//     the ground under the body, so it cannot be pumped: a stationary, lateral,
546	//     late-leg or far-end body projects to the same arc however long it wiggles,
547	//     and nothing at all can be earned past the next unreached vertex.
548	//   * A motion is only usable while the chain of real feet is unbroken. An
549	//     unsupported, unreferenced, reset, respawned or freshly seeded frame drops
550	//     the previous foot, and a null previous foot is never replaced by the
551	//     current one — a gap is a gap, and no crossing may be claimed across it.
552	//
553	// Nothing is granted, no timer, tolerance, corridor, vertex, C or arrival rule
554	// changes here, and `routeProgressUnits` above is untouched.
555	
556	/** Unchanged route-vertex reach: how close the body must pass to round a vertex. */
557	const ROUTE_VERTEX_REACH_UNITS = 0.35;
558	
559	/**
560	 * Live, non-persisted physical coverage of the common route.
561	 *
562	 * `units` mirrors the credited span, `reachedVertex` is the last route vertex
563	 * the body actually crossed and passed, and `foot` is its real last position.
564	 * None of it is stored, restored or trusted across a break: see
565	 * `syncedRouteCoverage`.
566	 */
567	export interface RouteCoverage {
568	  readonly units: number;
569	  readonly reachedVertex: number;
570	  readonly foot: CommonGroundPoint | null;
571	}
572	
573	export const NO_ROUTE_COVERAGE: RouteCoverage = Object.freeze({
574	  units: 0,
575	  reachedVertex: 0,
576	  foot: null
577	});
578	
579	/** Arc length from the head of the route to `index`. */
580	function arcAtVertex(route: readonly CommonGroundPoint[], index: number): number {
581	  let arc = 0;
582	  for (let i = 1; i <= index && i < route.length; i += 1) {
583	    arc += distanceBetween(route[i - 1], route[i]);
584	  }
585	  return arc;
586	}
587	
588	/**
589	 * The last vertex a span of `units` PROVES was rounded.
590	 *
591	 * Strictly below the credit, deliberately. Credit sitting exactly on a vertex's
592	 * arc does not prove that vertex was passed — the recorded early cut pins at
593	 * exactly 4 without ever coming within 0.35 of (-42, ., 16) — so a span that has
594	 * to be re-derived, rather than carried live, always re-derives the conservative
595	 * answer and makes the body cross the corner again.
596	 */
597	function provenVertex(route: readonly CommonGroundPoint[], units: number): number {
598	  let proven = 0;
599	  let arc = 0;
600	  for (let index = 1; index < route.length; index += 1) {
601	    arc += distanceBetween(route[index - 1], route[index]);
602	    if (arc + 1e-9 < units) proven = index;
603	  }
604	  return proven;
605	}
606	
607	/**
608	 * Coverage re-seeded against the authoritative credited span.
609	 *
610	 * The snapshot owns the units. Whenever they differ from what this state last
611	 * saw — a resumed leg, a migrated save, a rewritten span, an actor or world
612	 * swap — the reached vertex is re-derived conservatively and the foot chain is
613	 * dropped, so nothing earned elsewhere is inherited as permission to move on.
614	 */
615	export function syncedRouteCoverage(
616	  route: readonly CommonGroundPoint[],
617	  coverage: RouteCoverage,
618	  units: number
619	): RouteCoverage {
620	  if (Math.abs(coverage.units - units) <= 1e-9) return coverage;
621	  return { units, reachedVertex: provenVertex(route, units), foot: null };
622	}
623	
624	/** Signed distance along the incoming leg, measured from `route[index]`. */
625	function planeOffset(
626	  route: readonly CommonGroundPoint[],
627	  index: number,
628	  body: CommonGroundPoint
629	): number {
630	  const from = route[index - 1];
631	  const at = route[index];
632	  const length = distanceBetween(from, at);
633	  if (!(length > 0)) return 0;
634	  return ((body.x - at.x) * (at.x - from.x)
635	    + (body.y - at.y) * (at.y - from.y)
636	    + (body.z - at.z) * (at.z - from.z)) / length;
637	}
638	
639	/** Closest approach of the real motion `from`->`to` to `point`. */
640	function segmentApproach(
641	  from: CommonGroundPoint,
642	  to: CommonGroundPoint,
643	  point: CommonGroundPoint
644	): number {
645	  const dx = to.x - from.x;
646	  const dy = to.y - from.y;
647	  const dz = to.z - from.z;
648	  const lengthSq = dx * dx + dy * dy + dz * dz;
649	  if (!(lengthSq > 0)) return distanceBetween(from, point);
650	  const t = Math.max(0, Math.min(1,
651	    ((point.x - from.x) * dx + (point.y - from.y) * dy + (point.z - from.z) * dz) / lengthSq));
652	  return distanceBetween(point, {
653	    x: from.x + dx * t,
654	    y: from.y + dy * t,
655	    z: from.z + dz * t
656	  });
657	}
658	
659	/**
660	 * Position on the leg out of `reachedVertex`, or null when the body is not on it.
661	 *
662	 * The arc can never leave that leg: the far vertex bounds it until an actual
663	 * crossing reaches it, which is why no amount of movement beyond an unreached
664	 * corner is worth anything.
665	 */
666	function coveredOnReachedLeg(
667	  route: readonly CommonGroundPoint[],
668	  reachedVertex: number,
669	  body: CommonGroundPoint,
670	  corridorRadius: number
671	): number | null {
672	  const next = reachedVertex + 1;
673	  if (next >= route.length) return arcAtVertex(route, reachedVertex);
674	  const from = route[reachedVertex];
675	  const to = route[next];
676	  const segment = distanceBetween(from, to);
677	  if (!(segment > 0)) return null;
678	  const dx = to.x - from.x;
679	  const dy = to.y - from.y;
680	  const dz = to.z - from.z;
681	  const t = Math.max(0, Math.min(1,
682	    ((body.x - from.x) * dx + (body.y - from.y) * dy + (body.z - from.z) * dz)
683	      / (segment * segment)));
684	  const closest = { x: from.x + dx * t, y: from.y + dy * t, z: from.z + dz * t };
685	  if (distanceBetween(body, closest) > corridorRadius) return null;
686	  return arcAtVertex(route, reachedVertex) + segment * t;
687	}
688	
689	/**
690	 * Next credited span, from the body's ACTUAL motion over the route.
691	 *
692	 * `coverage.foot` is the real previous foot and is never synthesised from the
693	 * current one. With no previous foot the motion is unknown, so this update
694	 * records the foot and credits nothing at all.
695	 */
696	export function nextRouteCoverage(
697	  route: readonly CommonGroundPoint[],
698	  body: CommonGroundPoint,
699	  displacementUnits: number,
700	  coverage: RouteCoverage,
701	  corridorRadius = 2.5,
702	  vertexReach = ROUTE_VERTEX_REACH_UNITS
703	): RouteCoverage {
704	  const foot = { x: body.x, y: body.y, z: body.z };
705	  const previous = coverage.foot;
706	  // NO MOTION, NO COVERAGE, and no chain either: a body that has not moved has
707	  // covered nothing, however long it stands there and however often it is
708	  // sampled. Standing at C is still worth exactly zero.
709	  if (!previous || !(displacementUnits > 0)) {
710	    return { units: coverage.units, reachedVertex: coverage.reachedVertex, foot };
711	  }
712	
713	  // ONE VERTEX AT A TIME, IN ORDER, each by an actual crossing of its incoming
714	  // plane made by this very motion, and each within the unchanged vertex reach.
715	  let reachedVertex = coverage.reachedVertex;
716	  while (reachedVertex + 1 < route.length) {
717	    const next = reachedVertex + 1;
718	    const crossed = planeOffset(route, next, previous) < 0
719	      && planeOffset(route, next, foot) >= 0;
720	    if (!crossed) break;
721	    if (segmentApproach(previous, foot, route[next]) > vertexReach) break;
722	    reachedVertex = next;
723	  }
724	
725	  const onLeg = coveredOnReachedLeg(route, reachedVertex, foot, corridorRadius);
726	  const reachedArc = arcAtVertex(route, reachedVertex);
727	  const covered = Math.max(
728	    coverage.units,
729	    reachedVertex > coverage.reachedVertex ? reachedArc : coverage.units,
730	    onLeg ?? coverage.units
731	  );
732	  return { units: covered, reachedVertex, foot };
733	}
734	
735	// --- Display grammar ------------------------------------------------------------------
736	//
737	// PURE PLACEMENT MATH, no THREE and no mesh. The renderer turns each placement
738	// into one instance matrix in the existing pooled unit-box mesh, so the shape a
739	// player reads is decided here and can be asserted without a GPU.

