  // --- The lifecycle around that one exception -------------------------------------
  //
  // Not cancelling on the done frame must not quietly turn a finished story back
  // into a foreground one. These run the same shipped callback and assert what it
  // actually does with the rest of the frame.

  it('does not tick the story director on the normal handback frame', () => {
